import { useBlockProps, RichText } from '@wordpress/block-editor';

export default function save({ attributes }) {
  const { items, scheme, heading, bodyText } = attributes;

  return (
    <section {...useBlockProps.save({ className: `carousel-section ${scheme}` })}>
        <div class="container">

          <RichText.Content
              class="section-heading fade-in-up"
              tagName="h2"
              value={heading} 
          />

          <RichText.Content
              class="section-body fade-in-up"
              tagName="p"
              value={bodyText} 
          />
          <div class="carousel swiper swiper-carousel fade-in-up">
            <div class="swiper-buttons-wrapper">
              <div class="swiper-button-prev">
                <svg class="icon" width="56" height="32" title="Previous slide">
                      <use href="/wp-content/themes/lone-pine-digital/assets/iconsprite.svg#arrowLeft"/>
                  </svg>
              </div>
              <div class="swiper-button-next">
                <svg class="icon" width="56" height="32" title="Next slide">
                  <use href="/wp-content/themes/lone-pine-digital/assets/iconsprite.svg#arrowRight"/>
                </svg>
              </div>
            </div>
            <div class="swiper-wrapper">
              {items.map((item, index) => (
                  <div key={index} class="carousel-item swiper-slide">
                    <div class="carousel-item-wrapper">
                      <div class="carousel-inner">
                        <div class='carousel-item-icon'>
                          <img src={item.icon} alt={item.title} loading="eager" />
                        </div>
                        <RichText.Content
                          tagName="h3"
                          class="h4 carousel-item-title"
                          value={item.title}
                        />
                        <RichText.Content
                          tagName="p"
                          class="carousel-item-content"
                          value={item.text}
                        />
                        {item.link?.url && (
                          <a
                              href={item.link.url}
                              className="carousel-item-link btn btn-primary"
                              {...(item.link.opensInNewTab && {
                                  target: '_blank',
                                  rel: 'noopener noreferrer',
                              })}
                          >
                              Read more
                          </a>
                        )}
                      </div>
                    </div>
                  </div>
              ))}
            </div>
          </div>
        </div>
    </section>
  );
}