import { useState } from '@wordpress/element';
import {
    useBlockProps,
    RichText,
    InspectorControls,
    MediaUploadCheck,
    MediaUpload,
    __experimentalLinkControl as LinkControl, // use `LinkControl` if your WP version exports it as stable
} from '@wordpress/block-editor';

import {
    Button,
    PanelBody,
    SelectControl,
    Popover
} from '@wordpress/components';

export default function Edit({ attributes, setAttributes }) {
    const { items = [], heading, scheme, bodyText } = attributes;

    const [openLinkIndex, setOpenLinkIndex] = useState(null);

    const blockProps = useBlockProps({
        className: `carousels ${scheme}`
    });

    const updateItem = (index, field, value) => {
        const newItems = [...items];
        newItems[index] = {
            ...newItems[index],
            [field]: value
        };
        setAttributes({ items: newItems });
    };

    const addItem = () => {
        setAttributes({
            items: [
                ...items,
                { title: '', text: '', icon: '', link: undefined }
            ]
        });
    };

    return (
        <>
            <InspectorControls>
                <PanelBody title="Carousels Scheme" initialOpen={true}>
                    <SelectControl
                        label="Colour Scheme"
                        value={scheme}
                        options={[
                            { label: 'Eggshell', value: 'eggshell' },
                            { label: 'Evergreen', value: 'evergreen' },
                            { label: 'Celadon', value: 'celadon' }
                        ]}
                        onChange={(value) => setAttributes({ scheme: value })}
                    />
                </PanelBody>
            </InspectorControls>

            <div {...blockProps}>

                <RichText
                    tagName="h2"
                    value={heading}
                    onChange={(value) => setAttributes({ heading: value })}
                    placeholder="Add section heading…"
                />

                <RichText
                    tagName="p"
                    value={bodyText}
                    onChange={(value) => setAttributes({ bodyText: value })}
                    placeholder="Add text…"
                />

                    {items.map((item, index) => (
                        <div key={index} className="carousel-item">

                            <MediaUploadCheck>
                                <MediaUpload
                                    onSelect={(media) => updateItem(index, 'icon', media.url)}
                                    allowedTypes={['image']}
                                    render={({ open }) => (
                                        <Button onClick={open} variant="primary">
                                            {item.icon ? 'Change Image' : 'Select Image'}
                                        </Button>
                                    )}
                                />
                            </MediaUploadCheck>
            
                            {item.icon && <img src={item.icon} alt="" />}

                            <RichText
                                tagName="h3"
                                className="h4 carousel-item-title"
                                value={item.title}
                                onChange={(value) =>
                                    updateItem(index, 'title', value)
                                }
                                placeholder="Carousel item title…"
                            />

                            <RichText
                                tagName="p"
                                className="carousel-item-content"
                                value={item.text}
                                onChange={(value) =>
                                    updateItem(index, 'text', value)
                                }
                                placeholder="Carousel item text…"
                            />

                            <div className="carousel-item-link">
                                <Button
                                    variant="secondary"
                                    onClick={() =>
                                        setOpenLinkIndex(openLinkIndex === index ? null : index)
                                    }
                                >
                                    {item.link?.url ? 'Edit Link' : 'Add Link'}
                                </Button>
                                
                                {item.link?.url && (
                                    <>
                                        <span className="carousel-item-link-url">
                                            {item.link.title || item.link.url}
                                        </span>
                                        <Button
                                            variant="tertiary"
                                            isDestructive
                                            onClick={() => updateItem(index, 'link', undefined)}
                                        >
                                            Remove
                                        </Button>
                                    </>
                                     )}
        
                                {openLinkIndex === index && (
                                    <Popover
                                        position="bottom center"
                                        onClose={() => setOpenLinkIndex(null)}
                                        focusOnMount="firstElement"
                                    >
                                        <div style={{ minWidth: 320 }}>
                                            <LinkControl
                                                value={item.link}
                                                settings={[
                                                    {
                                                        id: 'opensInNewTab',
                                                        title: 'Open in new tab',
                                                    },
                                                ]}
                                                onChange={(newLink) => updateItem(index, 'link', newLink)}
                                                onRemove={() => {
                                                    updateItem(index, 'link', undefined);
                                                    setOpenLinkIndex(null);
                                                }}
                                            />
                                        </div>
                                    </Popover>
                                )}
                            </div>
                        </div>
                    ))}

                <Button
                    variant="primary"
                    onClick={addItem}
                >
                    Add Item
                </Button>
            </div>
        </>
    );
}